import "../../src/nim_cryptkit/hash/esch"
import "../../src/nim_cryptkit/utils/digits"
import std/[monotimes, times]

template benchmark(name: string, code: untyped) =
  let start = getMonoTime()
  code
  let elapsed = getMonoTime() - start
  echo name, " took: ", elapsed.inMicroseconds, " μs (", elapsed.inNanoseconds, " ns)"

var ctx256: ESCH256Ctx

var input256_1: seq[uint8] = hexToBin("00010203040506").value
echo "ESCH-256 Input 1 : ", binToHex(input256_1)
esch256Init(ctx256)
esch256Input(ctx256, input256_1)
var output256_1: array[32, uint8] = esch256Final(ctx256)
let hash256_1 = binToHex(output256_1)
echo "ESCH-256 Stream 1 : ", hash256_1
echo "ESCH-256 Standard 1: 12E076105E60FD4080CA7546340E180AAA4C277C1495E958DF869CEAF0843F2E"
doAssert hash256_1 == "12E076105E60FD4080CA7546340E180AAA4C277C1495E958DF869CEAF0843F2E", "ESCH-256 Test 1 Wrong!"
echo ""

var input256_2: seq[uint8] = hexToBin("000102030405060708090A").value
echo "ESCH-256 Input 2 : ", binToHex(input256_2)
esch256Init(ctx256)
esch256Input(ctx256, input256_2)
var output256_2: array[32, uint8] = esch256Final(ctx256)
let hash256_2 = binToHex(output256_2)
echo "ESCH-256 Stream 2 : ", hash256_2
echo "ESCH-256 Standard 2: 47FFAEE11BFEC90E49EF4671C25867123D8E24392B13A9C265C7970F33C16785"
doAssert hash256_2 == "47FFAEE11BFEC90E49EF4671C25867123D8E24392B13A9C265C7970F33C16785", "ESCH-256 Test 2 Wrong!"
echo ""

var input256_3: seq[uint8] = hexToBin("").value
echo "ESCH-256 Input 3 : ", binToHex(input256_3)
esch256Init(ctx256)
esch256Input(ctx256, input256_3)
var output256_3: array[32, uint8] = esch256Final(ctx256)
let hash256_3 = binToHex(output256_3)
echo "ESCH-256 Stream 3 : ", hash256_3
echo "ESCH-256 Standard 3: 2EFD300525B3A4FE87933334E2C87AFFEFB65B4F59BD72C2AF3F7A69740D0D15"
doAssert hash256_3 == "2EFD300525B3A4FE87933334E2C87AFFEFB65B4F59BD72C2AF3F7A69740D0D15", "ESCH-256 Test 3 Wrong!"
echo ""

var ctx384: ESCH384Ctx

var input384_1: seq[uint8] = hexToBin("00010203").value
echo "ESCH-384 Input 1 : ", binToHex(input384_1)
esch384Init(ctx384)
esch384Input(ctx384, input384_1)
var output384_1: array[48, uint8] = esch384Final(ctx384)
let hash384_1 = binToHex(output384_1)
echo "ESCH-384 Stream 1 : ", hash384_1
echo "ESCH-384 Standard 1: 900C76A75AD5FEC6924934E8EADC78BCB3951E241A2AC9301E6D35895689BA7C93411A5B6DEF5A2F87248AFF1BDD240E"
doAssert hash384_1 == "900C76A75AD5FEC6924934E8EADC78BCB3951E241A2AC9301E6D35895689BA7C93411A5B6DEF5A2F87248AFF1BDD240E", "ESCH-384 Test 1 Wrong!"
echo ""

var input384_2: seq[uint8] = hexToBin("000102030405060708090A0B0C0D0E0F10111213141516").value
echo "ESCH-384 Input 2 : ", binToHex(input384_2)
esch384Init(ctx384)
esch384Input(ctx384, input384_2)
var output384_2: array[48, uint8] = esch384Final(ctx384)
let hash384_2 = binToHex(output384_2)
echo "ESCH-384 Stream 2 : ", hash384_2
echo "ESCH-384 Standard 2: DCAD7D7394C64CB59BE79EE06A42FE5A420C5718156C6D3CC44ED07E699DDBE79BB2919D65EC4A24B5ECE4AFB11DFF54"
doAssert hash384_2 == "DCAD7D7394C64CB59BE79EE06A42FE5A420C5718156C6D3CC44ED07E699DDBE79BB2919D65EC4A24B5ECE4AFB11DFF54", "ESCH-384 Test 2 Wrong!"
echo ""

var input384_3: seq[uint8] = hexToBin("").value
echo "ESCH-384 Input 3 : ", binToHex(input384_3)
esch384Init(ctx384)
esch384Input(ctx384, input384_3)
var output384_3: array[48, uint8] = esch384Final(ctx384)
let hash384_3 = binToHex(output384_3)
echo "ESCH-384 Stream 3 : ", hash384_3
echo "ESCH-384 Standard 3: 9A3A811A27053E3CD4D7F09FA6190C64FF2014D311BCD2F70390DA38A99980B35F07F1DD9D93434D8A98552069D8E228"
doAssert hash384_3 == "9A3A811A27053E3CD4D7F09FA6190C64FF2014D311BCD2F70390DA38A99980B35F07F1DD9D93434D8A98552069D8E228", "ESCH-384 Test 3 Wrong!"
echo ""

var ctx224: ESCH224Ctx
var ctx512: ESCH512Ctx

var res224: array[28, uint8]
var res256: array[32, uint8]
var res384: array[48, uint8]
var res512: array[64, uint8]

benchmark("ESCH-224"):
  for i in 1 .. 1_000_000:
    esch224Init(ctx224)
    esch224Input(ctx224, res224)
    res224 = esch224Final(ctx224)

benchmark("ESCH-256"):
  for i in 1 .. 1_000_000:
    esch256Init(ctx256)
    esch256Input(ctx256, res256)
    res256 = esch256Final(ctx256)

benchmark("ESCH-384"):
  for i in 1 .. 1_000_000:
    esch384Init(ctx384)
    esch384Input(ctx384, res384)
    res384 = esch384Final(ctx384)

benchmark("ESCH-512"):
  for i in 1 .. 1_000_000:
    esch512Init(ctx512)
    esch512Input(ctx512, res512)
    res512 = esch512Final(ctx512)
